const body = $('Webhook').first().json.body || {};

const requiredFields = [
  'item_id',
  'answer',
  'resolved_category',
  'resolved_title'
];

const missing = requiredFields.filter(
  key => !body[key] ||
    String(body[key]).trim() === ''
);

if (missing.length > 0) {
  throw new Error(
    'Missing required fields: ' + missing.join(', ')
  );
}

// Validate UUID format
const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (!uuidPattern.test(body.item_id)) {
  throw new Error('Invalid item_id.');
}

// Only allow valid scope categories
const allowedCategories = [
  'deliverable',
  'included',
  'excluded',
  'client_responsibility'
];

if (!allowedCategories.includes(body.resolved_category)) {
  throw new Error('Invalid resolution category.');
}

// Require explicit freelancer confirmation
if (body.confirmed_by_freelancer !== true) {
  throw new Error(
    'Freelancer approval is required before resolving this item.'
  );
}

// Require authenticated user's JWT
const authorization =
  $('Webhook').first().json.headers?.authorization;

if (
  !authorization ||
  !authorization.startsWith('Bearer ')
) {
  throw new Error('Authenticated Supabase user token is required.');
}

return [{
  json: {
    success: true,
    item_id: body.item_id,
    answer: body.answer.trim(),
    resolved_category: body.resolved_category,
    resolved_title: body.resolved_title.trim(),
    resolved_description:
      body.resolved_description?.trim() || body.answer.trim()
  }
}];

const request = $('Validate Resolution Input').first().json;
const result = $input.first().json;

return [{
  json: {
    success: true,
    message: "تم تحديث البند بنجاح.",
    item_id: request.item_id,
    resolved_category: request.resolved_category,
    resolved_title: request.resolved_title,
    database_result: result
  }
}];
